<?php
use PHPUnit\Framework\TestCase;use ZinCelestial\Platform\Compliance\{ComplianceControl,ComplianceEngine};
final class ComplianceEngineIntegrationTest extends TestCase{public function test_valid_fresh_hashed_evidence_passes():void{$e=new ComplianceEngine();$e->register(new ComplianceControl('access.review','soc2','high',['access_review'],86400));$r=$e->evaluate('access.review',[['id'=>'ev-1','type'=>'access_review','collected_at'=>1000,'sha256'=>str_repeat('a',64)]],1100);$this->assertSame('pass',$r->status);$this->assertSame(['ev-1'],$r->evidence_ids);}public function test_stale_evidence_fails():void{$e=new ComplianceEngine();$e->register(new ComplianceControl('backup.restore','soc2','critical',['restore_test'],60));$r=$e->evaluate('backup.restore',[['id'=>'ev','type'=>'restore_test','collected_at'=>1,'sha256'=>str_repeat('b',64)]],1000);$this->assertSame('fail',$r->status);$this->assertContains('stale_evidence',$r->reasons);}public function test_unknown_control_is_denied():void{$this->expectException(RuntimeException::class);(new ComplianceEngine())->evaluate('missing',[],time());}}
